import * as T from './vendor/three.module.js';
// Read the engine's existing center-wide, current-day water cooldown; no new save fields.
export function waterAvailability(s){const last=(s.amenityUses||[]).slice().reverse().find(n=>n.id==='water'&&n.mallId===s.mallId&&n.day===s.day),remaining=last?Math.max(0,30-(s.minutes-last.minutes)):0;return {remaining:Math.ceil(remaining),ready:remaining<=0,recent:!!last};}
export function waterPanelHTML(s,esc,{bottleName='',nearby=''}={}){const v=waterAvailability(s);return `<div class="modal-body water-station"><div class="water-illustration" aria-hidden="true">💧</div><h3>${bottleName?'Refill your '+esc(bottleName)+' bottle.':'A cup of water, on us.'}</h3><p>Take a drink before the next shop. Water restores 8 stamina without replacing a meal. Come back after 30 game minutes if you need another.</p><p class="water-readiness" role="status">${v.ready?'Ready for a water break.':`Ready in ${v.remaining} game minutes.`} This cooldown is shared by water stops on every floor of this center.</p><p>Current stamina ${Math.round(s.energy)}/100 · restores up to 8 after 3 game minutes. Normal time costs still apply. Reading this card changes no money, time or XP.</p><button class="button orange wide" data-action="water-use" ${v.ready?'':'disabled'}>${v.ready?(bottleName?'Refill & drink':'Take a cup & drink')+' · free · 3 min':'Ready in '+v.remaining+' game minutes'}</button>${nearby}<button class="text-button" data-action="guest-services">Back to guest services</button></div>`;}
export function buildWaterHousing(b,x,z,theme){
 for(const dx of[-8,-4,0,4,8])b.box(x+dx,17,z+9.1,1.1,25,.7,theme.trim,0,'metal');
 b.box(x,34,z,21,2,17,'#c1cdc6',0,'metal');b.box(x,35,z+1,14,.4,11,'#738e88');for(let i=0;i<5;i++)b.box(x-5+i*2.5,35.4,z+3,.5,.3,6,'#d0dcd2',0,'metal');
 b.box(x,42,z-6,18,14,5,'#5d7772',0,'metal');b.box(x,48.5,z-3.2,12,2,.6,'#d5e1d6');b.box(x,41,z-3.1,5,5,.6,'#405d57');b.box(x,35.7,z+1,11,.3,8,'#9fb6ad');
 for(const dx of[-8,8])b.box(x+dx,36,z+5,4,.8,5,'#d4c7ab');
}
export function buildWaterDetail(w,x,z,theme){
 const root=new T.Group();root.position.set(x,0,z);w.scene.add(root);const metal=w.mat('#bccbc5',{metalness:.6,roughness:.26}),paper=w.mat('#eee6d6',{roughness:.9}),glass=w.mat('#96b7ac',{roughness:.3}),status=new T.MeshStandardMaterial({color:'#80b7b3',emissive:'#47766c',emissiveIntensity:.2,roughness:.45});w.resources.add(status);
 const add=(g,m,p,scale)=>{const a=w.mesh(g,m,root);a.position.set(...p);if(scale)a.scale.set(...scale);return a;};
 const curve=new T.CatmullRomCurve3([[-4,35,-3],[-4,47,-3],[-2,50,-3],[1,49,-1],[1,44,1]].map(a=>new T.Vector3(...a)));add(new T.TubeGeometry(curve,20,.65,8,false),metal,[0,0,0]);
 const cup=new T.LatheGeometry([[0,0],[1.3,0],[1.8,4],[1.55,4],[1.1,.3],[0,.3]].map(p=>new T.Vector2(...p)),20),cups=new T.InstancedMesh(cup,paper,4),dummy=new T.Object3D();w.resources.add(cup);for(let i=0;i<4;i++){dummy.position.set(8,36+i*.7,5);dummy.updateMatrix();cups.setMatrixAt(i,dummy.matrix);}cups.instanceMatrix.needsUpdate=true;cups.computeBoundingSphere();cups.castShadow=cups.receiveShadow=true;root.add(cups);
 add(new T.CylinderGeometry(1.5,1.65,8,16),glass,[-8,40.4,5]);add(new T.CylinderGeometry(.7,.7,2.5,12),glass,[-8,45.5,5]);add(new T.CylinderGeometry(.9,.9,1,12),metal,[-8,47.3,5]);
 const ripple=add(new T.TorusGeometry(3,.12,4,24),w.mat('#c6d9cf'),[0,35.9,1]);ripple.rotation.x=Math.PI/2;const lamp=add(new T.SphereGeometry(1.1,8,6),status,[6,45,-3.1]),level=add(new T.BoxGeometry(1.3,7,.5),status,[-7,43,-3.1]);root.userData={originalWaterStation:true,footprint:{width:22,depth:20}};w.waterStations??=[];w.waterStations.push({root,lamp,level,ripple,status,signature:null});w.canvas.dataset.waterDetailRevision='49';updateWaterDetails(w);return root;
}
export function updateWaterDetails(w){const v=waterAvailability(w.state),key=v.remaining;for(const a of w.waterStations||[]){if(a.signature!==key){a.status.color.set(v.ready?'#80b7b3':'#c69c66');a.status.emissive.set(v.ready?'#47766c':'#805a35');a.level.scale.y=.12+.88*(1-Math.min(30,v.remaining)/30);a.level.position.y=39.5+3.5*a.level.scale.y;a.signature=key;}const k=w.state.preferences.reducedMotion?1:1+Math.sin((Number.isFinite(w.t)?w.t:0)*1.2)*.025;a.ripple.scale.set(k,k,1);}if(w.waterStations?.length)w.canvas.dataset.waterReadyIn=String(v.remaining);}
